// memory-manager.js
const cron = require('node-cron');
const { fragmentAndPackage } = require('./scripts/fragment_and_package_conversations');
const { extractCodeFragments } = require('./scripts/extract_code_fragments');
const { depositContent } = require('./scripts/fragment_and_package_conversations');

// Load job schedule from YAML
const jobsConfig = require('./config/memory-jobs.yaml');

// Register jobs
jobsConfig.jobs.forEach(job => {
  cron.schedule(job.cron, async () => {
    console.log(`Running job: ${job.name}`);
    switch(job.task) {
      case 'fragmentChats':
        await fragmentAndPackage();
        break;
      case 'extractCode':
        await extractCodeFragments();
        break;
      case 'poeticScan':
        // scan specified folder
        const files = fs.readdirSync(job.folder);
        for(const f of files) {
          const content = fs.readFileSync(path.join(job.folder, f), 'utf8');
          const poem = await PoetryAgent.generateVerse(content);
          depositContent(job.folderPoems, { file: f, poem }, { processor:'poeticAgent' });
        }
        break;
      case 'scienceScan':
        // similar: ScienceAgent.classifyFiles
        break;
      default:
        console.warn(`Unknown task: ${job.task}`);
    }
  }, { timezone: 'Europe/Berlin' });
});

console.log('MemoryManager started with scheduled jobs.');
```

